mod.css:
html, body, .page, .mast, .foot, nav[aria-label="Contents"], .ibox, .art, .body, section[aria-label="Comments"], .c {
  background-color: #1b1d1f !important;
  color: #e8eaed !important;
}
.mast, .foot, nav[aria-label="Contents"] { background-color: #121314 !important; }
a { color: #8ab4f8 !important; }
a:visited { color: #c58af9 !important; }
h1, h2, h3, h4, .sub { color: #f1f3f4 !important; border-color: #3c4043 !important; }
input[aria-label="Search\ Openpedia"] {
  background-color: #2a2c2e !important;
  color: #e8eaed !important;
  border-color: #5f6368 !important;
}
button { background-color: #2a2c2e !important; color: #e8eaed !important; border-color: #5f6368 !important; }
.ibox, table, th, td { border-color: #3c4043 !important; }
